func:
// Normaliza a leitura do ESP32 e calcula a potência instantânea (P = V·I).
const l = msg.payload || {};
const tensao = Number(l.tensao_v) || 0;
const corrente = Number(l.corrente_a) || 0;
const kwh = Number(l.energia_kwh) || 0;

msg.payload = {
    casaId: l.casaId || 'device-01',
    data_hora: l.data_hora || null,
    tensao_v: tensao,
    corrente_a: corrente,
    potencia_w: Number((tensao * corrente).toFixed(4)),
    energia_kwh: kwh,
    energia_wh: Number((kwh * 1000).toFixed(4)),
};

// energia_kwh é ACUMULADA desde o boot; o delta entre leituras é o consumo.
const ant = flow.get('ultimoKwh_' + msg.payload.casaId);
msg.payload.delta_wh = (typeof ant === 'number' && kwh >= ant)
    ? Number(((kwh - ant) * 1000).toFixed(4))
    : 0;
flow.set('ultimoKwh_' + msg.payload.casaId, kwh);

node.status({ fill: 'green', shape: 'dot',
    text: msg.payload.potencia_w + ' W · ' + msg.payload.energia_wh + ' Wh' });
return msg;

// Contrato do firmware em satsmeter/comandos: '1' liga o relé, '0' corta.
const v = String(msg.payload).trim();
const ligado = v === '1';
msg.payload = { comando: v, releLigado: ligado, ts: Date.now() };
node.status({ fill: ligado ? 'green' : 'red', shape: 'dot',
    text: ligado ? 'relé ligado' : 'relé cortado' });
return msg;

// Achata /api/metrics nos números que interessam ao painel.
const m = msg.payload || {};
const casa = (m.casas || [])[0] || {};
msg.payload = {
    liquidacoes: m.liqTotal,
    satsAoProdutor: m.satsTotal,
    energiaKwh: m.energiaKwh,
    cortes: m.cortes,
    religas: m.religas,
    casasAtivas: m.casasAtivas,
    casaId: casa.casaId,
    saldoSats: casa.saldoSats,
    releLigado: casa.releLigado,
    falhasPagamento: casa.falhasPagamento,
};
node.status({ fill: 'blue', shape: 'dot',
    text: msg.payload.liquidacoes + ' liq · ' + Math.round(msg.payload.saldoSats || 0) + ' sats' });
return msg;
